   if(lookupError)throw lookupError;
   if(existing?.[0]){location.hash="#/challenge";return}
   const {data:app,error:insertError}=await db.from("titan_applications").insert({user_id:user.id,rules_accepted_at:new Date().toISOString()}).select().single();
   if(insertError)throw insertError;
   if(!app?.id)throw new Error("Application could not be confirmed.");
   const {error:progressError}=await db.from("titan_pillar_progress").upsert(["fitness","mindset","lifestyle","discipline"].map(p=>({user_id:user.id,application_id:app.id,pillar_code:p,status:p==="fitness"?"active":"locked"})),{onConflict:"user_id,application_id,pillar_code"});
