async function challenge(){const {data:{user}}=await db.auth.getUser();if(!user)return location.hash="#/apply";const {data:a}=await db.from("titan_applications").select("id,status").eq("user_id",user.id).in("status",["in_progress","under_review","passed","reattempt"]).order("created_at",{ascending:false}).limit(1).single();if(!a)return location.hash="#/apply";window.applicationId=a.id;const {data:sessions}=await db.from("titan_sessions").select("*,titan_challenges(slug,name)").eq("application_id",a.id).order("created_at",{ascending:false});const approved=new Set((sessions||[]).filter(x=>x.status==="approved").map(x=>x.challenge_id));const fitnessComplete=approved.size>=5;const cards=C.map(c=>{const x=(sessions||[]).find(s=>s.titan_challenges?.slug===c[0]&&["under_review","approved"].includes(s.status));return '<article class="trial"><p class="eyebrow">'+c[0].toUpperCase()+'</p><h3>'+c[1]+'</h3><strong>'+c[2]+'</strong><p>'+(!x?"Not submitted":x.status==="approved"?"✓ Approved":"◷ Under review")+'</p>'+(!x?'<button class="btn" onclick="startTrial(\''+c[0]+'\')">Start</button>':x.status==="under_review"?'<span class="status">Waiting for review</span>':'<span class="status">Passed</span>')+'</article>'}).join("");shell('<section class="pagehead"><p class="eyebrow">⚔️ PILLAR I · FITNESS</p><h1>THE PHYSICAL TRIAL</h1><p>Complete all five physical tests. Approval unlocks the seven-day trials.</p></section><section class="section"><div class="grid five">'+cards+'</div><div class="center" style="margin-top:30px">'+(fitnessComplete?'<a class="btn primary" href="#/execution">Continue to 7-Day Trials →</a>':'<p class="muted">All five Fitness tests must be approved before the next pillar stage unlocks.</p>')+'</div><div id="capture"></div></section>')}window.startTrial=async slug=>{const {data:{user}}=await db.auth.getUser();const {data:ch,error:ce}=await db.from("titan_challenges").select("*").eq("slug",slug).single();if(ce)return toast(ce.message);const code="OR-"+crypto.randomUUID().slice(0,8).toUpperCase();const {data,error}=await db.from("titan_sessions").insert({application_id:window.applicationId,user_id:user.id,challenge_id:ch.id,challenge_code:code}).select().single();if(error)return toast(error.message);current=data;if(slug==="run_2k")return runUI();captureUI(slug,code)};function captureUI(slug,code){const label=C.find(c=>c[0]===slug)?.[1]||slug.toUpperCase();document.querySelector("#capture").innerHTML='<div class="capture"><div class="capturebar"><b>'+esc(code)+'</b><b>'+esc(label)+'</b></div><div class="card"><p class="eyebrow">STEP 1</p><h3>Prepare</h3><p>Place the phone where your full movement is visible. Keep the area safe and well lit.</p><p class="eyebrow">STEP 2</p><h3>Show the code</h3><p>Keep <b>'+esc(code)+'</b> visible to the camera before starting.</p><p class="eyebrow">STEP 3</p><h3>Record continuously</h3><p>Do not leave the challenge screen or stop the recording during your attempt.</p></div><video id="video" autoplay muted playsinline></video><div class="actions"><button class="btn primary" id="record">Start Recording</button><button class="btn" id="stop" disabled>Stop & Submit</button></div><div class="timer" id="timer">00:00</div><p class="muted center">Your submission will be reviewed before approval.</p></div>';document.querySelector("#record").onclick=startRecord;document.querySelector("#stop").onclick=stopRecord}async function startRecord(){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});document.querySelector("#video").srcObject=stream;chunks=[];visibilityEvents=0;recordChunkCount=0;recordStartedAt=new Date().toISOString();recordMime="";rec=new MediaRecorder(stream);recordMime=rec.mimeType||"video/webm";rec.ondataavailable=e=>{if(e.data.size){chunks.push(e.data);recordChunkCount++}};rec.onstop=uploadVideo;rec.start(1000);document.querySelector("#record").disabled=true;document.querySelector("#stop").disabled=false;let s=0;window.timer=setInterval(()=>document.querySelector("#timer").textContent=new Date(++s*1000).toISOString().slice(14,19),1000);document.addEventListener("visibilitychange",handleVisibility)}catch(e){toast("Camera permission is required.")}}function handleVisibility(){if(document.visibilityState==="hidden")visibilityEvents++;}function stopRecord(){clearInterval(window.timer);document.removeEventListener("visibilitychange",handleVisibility);rec?.stop();stream?.getTracks().forEach(t=>t.stop())}async function uploadVideo(){const {data:{user}}=await db.auth.getUser();const blob=new Blob(chunks,{type:recordMime||"video/webm"});const duration=Math.max(0,Math.round((Date.now()-new Date(recordStartedAt).getTime())/1000));const bytes=new Uint8Array(await blob.arrayBuffer());const digest=await crypto.subtle.digest("SHA-256",bytes);const videoHash=Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,"0")).join("");const integritySignals={recordingMode:"continuous_mediarecorder",mimeType:recordMime,chunkCount:recordChunkCount,blobBytes:blob.size,videoSha256:videoHash,visibilityEvents,clientStart:recordStartedAt,clientEnd:new Date().toISOString(),durationSeconds:duration,notes:[]};if(visibilityEvents>0)integritySignals.notes.push("page_visibility_changed_during_recording");if(recordChunkCount<2)integritySignals.notes.push("very_few_recording_chunks");if(duration<3)integritySignals.notes.push("very_short_recording");if(blob.size<50000)integritySignals.notes.push("very_small_video");integritySignals.integrityStatus=integritySignals.notes.length?"review_flagged":"review";const path=user.id+"/"+current.id+"/"+current.challenge_code+".webm";const up=await db.storage.from("titan-videos").upload(path,blob,{contentType:recordMime||"video/webm"});if(up.error)return toast(up.error.message);const {data:appRow}=await db.from("titan_applications").select("id").eq("user_id",user.id).eq("id",current.application_id||"").maybeSingle();const applicationId=appRow?.id||current.application_id;if(!applicationId){await db.storage.from("titan-videos").remove([path]);return toast("Titan application not found.");}const {error}=await db.from("titan_submissions").insert({application_id:applicationId,session_id:current.id,user_id:user.id,challenge_id:current.challenge_id,video_path:path,video_duration_seconds:duration,integrity_status:integritySignals.integrityStatus,integrity_signals:integritySignals,client_metadata:{userAgent:navigator.userAgent,submittedAt:new Date().toISOString(),language:navigator.language,screenWidth:screen.width,screenHeight:screen.height}});if(error){await db.storage.from("titan-videos").remove([path]);return toast(error.message);}await db.from("titan_sessions").update({status:"under_review",ended_at:new Date().toISOString()}).eq("id",current.id);document.querySelector("#capture").innerHTML='<div class="capture center"><h2>SUBMISSION RECEIVED</h2><p>Your attempt is now awaiting ORANOS review.</p></div>'}function runUI(){document.querySelector("#capture").innerHTML='<div class="capture center"><div class="capturebar"><b>'+esc(current.challenge_code)+'</b><b>THE MARCH</b></div><div class="card"><p class="eyebrow">GPS TRIAL</p><h3>2 KM · UNDER 14 MINUTES</h3><p>Keep location permission enabled. Stay on the challenge screen and complete the route safely.</p></div><div class="metric"><b id="km">0.00</b><span> / 2.00 KM</span></div><div class="metric"><b id="elapsed">00:00</b></div><p id="gps" class="muted">GPS waiting…</p><div class="actions" style="justify-content:center"><button class="btn primary" id="runStart">Start GPS Run</button><button class="btn" id="runStop" disabled>Finish Run</button></div></div>';document.querySelector("#runStart").onclick=startRun;document.querySelector("#runStop").onclick=endRun}function meters(a,b){const R=6371000,r=x=>x*Math.PI/180,d1=r(b.lat-a.lat),d2=r(b.lon-a.lon),q=Math.sin(d1/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(d2/2)**2;return 2*R*Math.asin(Math.sqrt(q))}function startRun(){if(!navigator.geolocation)return toast("GPS is unavailable.");points=[];runStart=Date.now();document.querySelector("#runStart").disabled=true;document.querySelector("#runStop").disabled=false;runTimer=setInterval(()=>document.querySelector("#elapsed").textContent=new Date(Date.now()-runStart).toISOString().slice(14,19),1000);watch=navigator.geolocation.watchPosition(p=>{const x={lat:p.coords.latitude,lon:p.coords.longitude,t:Date.now(),accuracy:p.coords.accuracy,speed:p.coords.speed};if(points.length)points.distance=(points.distance||0)+meters(points[points.length-1],x);points.push(x);document.querySelector("#km").textContent=((points.distance||0)/1000).toFixed(2);document.querySelector("#gps").textContent="GPS active · ±"+Math.round(p.coords.accuracy||0)+"m accuracy"},{enableHighAccuracy:true,maximumAge:1000,timeout:10000})}async function endRun(){navigator.geolocation.clearWatch(watch);clearInterval(runTimer);const {data:{user}}=await db.auth.getUser();const d=points.distance||0,s=Math.round((Date.now()-runStart)/1000);const accuracies=points.map(p=>Number(p.accuracy||0)).filter(Number.isFinite);const badAccuracy=accuracies.filter(x=>x>50).length;let jumps=0,impossible=0;for(let i=1;i<points.length;i++){const dt=Math.max(0,(points[i].t-points[i-1].t)/1000),gap=meters(points[i-1],points[i]);if(gap>200&&dt<10)jumps++;if(points[i].speed!=null&&points[i].speed>12)impossible++;}const avgSpeed=s?d/s:0;const spoofSignals={pointCount:points.length,averageSpeedMps:Number(avgSpeed.toFixed(3)),maxReportedSpeedMps:Number(Math.max(0,...points.map(p=>Number(p.speed||0))).toFixed(3)),accuracy:{samples:accuracies.length,averageMeters:accuracies.length?Number((accuracies.reduce((a,b)=>a+b,0)/accuracies.length).toFixed(2)):null,over50m:badAccuracy},largeJumps:jumps,impossibleSpeedSamples:impossible,notes:[]};if(badAccuracy>Math.max(3,Math.ceil(points.length*.25)))spoofSignals.notes.push("high_gps_error_frequency");if(jumps)spoofSignals.notes.push("large_location_jump");if(impossible)spoofSignals.notes.push("unusually_high_reported_speed");const integrityStatus=spoofSignals.notes.length?"review_flagged":"review";const a=await db.from("titan_run_sessions").insert({session_id:current.id,user_id:user.id,distance_meters:d,elapsed_seconds:s,avg_speed_mps:avgSpeed,gps_accuracy_summary:spoofSignals.accuracy,route_points:points,spoof_signals:spoofSignals});if(a.error)return toast(a.error.message);const b=await db.from("titan_submissions").insert({session_id:current.id,user_id:user.id,challenge_id:current.challenge_id,gps_distance_meters:d,gps_elapsed_seconds:s,gps_route:points,integrity_status:integrityStatus,integrity_signals:spoofSignals});if(b.error)return toast(b.error.message);await db.from("titan_sessions").update({status:"under_review",ended_at:new Date().toISOString()}).eq("id",current.id);document.querySelector("#capture").innerHTML='<div class="capture center"><h2>RUN SUBMITTED</h2><p>'+((d/1000).toFixed(2))+' km recorded. Awaiting review.</p><p class="muted">'+(spoofSignals.notes.length?"Integrity signals flagged for reviewer.":"GPS integrity data captured for reviewer.")+'</p></div>'}async function dashboard(){
 const {data:{user},error:authError}=await db.auth.getUser();
 if(authError)return shell('<section class="pagehead center"><h1>ACCOUNT CHECK FAILED</h1><p>We could not verify your session. Please sign in again.</p><a class="btn primary" href="#/login">Sign in</a></section>');
 if(!user){location.hash="#/login";return}
 const [profileResult,appResult]=await Promise.all([
  db.from("profiles").select("full_name").eq("id",user.id).maybeSingle(),
  db.from("titan_applications").select("*,titan_passes(*),titan_outcomes(*)").eq("user_id",user.id).order("created_at",{ascending:false}).limit(1).maybeSingle()
 ]);
 if(appResult.error)return shell('<section class="pagehead center"><h1>DASHBOARD UNAVAILABLE</h1><p>We could not load your Titan status. Your account has not been changed.</p><button class="btn primary" onclick="location.reload()">Try again</button><a class="btn" href="#/community">Community</a></section>');
 const ap=appResult.data,p=profileResult.data;
 const name=esc(p?.full_name||user.user_metadata?.full_name||"MEMBER");
 const header='<section class="pagehead"><p class="eyebrow">MY ORANOS</p><h1>WELCOME, '+name+'</h1><p>Your member space for the ORANOS journey.</p><div class="actions"><a class="btn primary" href="#/titan">Titan</a><a class="btn" href="#/oternal">Oternal</a><button class="btn" id="memberSignOut" type="button">Sign out</button></div></section>';
 if(!ap){shell(header+'<section class="section"><div class="panel center"><p class="eyebrow">YOUR JOURNEY STARTS HERE</p><h2>NO TITAN APPLICATION YET</h2><p>Review the challenge and begin when you are ready.</p><a class="btn primary" href="#/apply">Begin Titan Application</a></div></section>');document.querySelector("#memberSignOut").onclick=async()=>{const {error}=await db.auth.signOut();if(error)return toast(error.message);location.hash="/"};return}
 const [sessionResult,checkResult]=await Promise.all([
  db.from("titan_sessions").select("status,challenge_id,titan_challenges(slug,name)").eq("application_id",ap.id),
  db.from("titan_daily_checkins").select("day_number,pillar_code,completed,checkin_date,reviewer_status").eq("application_id",ap.id).order("day_number")
 ]);
 if(sessionResult.error||checkResult.error)return shell(header+'<section class="section"><div class="panel center"><h2>PROGRESS TEMPORARILY UNAVAILABLE</h2><p>Your application is still saved. Refresh to retry loading its progress.</p><button class="btn primary" onclick="location.reload()">Retry</button></div></section>');
 const sessions=sessionResult.data||[],checks=checkResult.data||[];
 const approved=new Set(sessions.filter(x=>x.status==="approved").map(x=>x.challenge_id)).size;
 const days=[1,2,3,4,5,6,7].map(n=>({n,ok:new Set(checks.filter(x=>x.day_number===n&&x.completed).map(x=>x.pillar_code)).size===3}));
 const completedDays=days.filter(x=>x.ok).length,pass=ap.titan_passes?.[0],outcome=ap.titan_outcomes?.[0];
 const status=ap.status==="passed"?"TITAN PASS EARNED":ap.status==="failed"?"TITAN ATTEMPT FAILED":ap.status==="reattempt"?"REATTEMPT REQUIRED":ap.status==="under_review"?"UNDER REVIEW":"IN PROGRESS";
 const fitnessNames=["THE PUSH","THE ASCENT","THE SQUAT","THE HOLD","THE MARCH"];
 const sessionCards=fitnessNames.map(name=>{const x=sessions.find(s=>s.titan_challenges?.name===name);return '<div class="prog"><span>'+name+'</span><b>'+esc((x?.status||"NOT STARTED").toUpperCase())+'</b></div>'}).join("");
 const dayCards=days.map(d=>'<div class="daybox '+(d.ok?"complete":"")+'"><b>DAY '+d.n+'</b><span>'+(d.ok?"✓ COMPLETE":"PENDING")+'</span></div>').join("");
 shell(header+'<section class="section"><div class="grid four"><div class="panel"><p class="eyebrow">FITNESS</p><h2>'+approved+' / 5</h2><p>Approved physical trials</p></div><div class="panel"><p class="eyebrow">7-DAY STANDARD</p><h2>'+completedDays+' / 7</h2><p>Completed days</p></div><div class="panel"><p class="eyebrow">APPLICATION</p><h2>'+esc(ap.status.toUpperCase())+'</h2><p>'+status+'</p></div><div class="panel"><p class="eyebrow">TIMEZONE</p><h2>'+esc(ap.timezone||"Asia/Kolkata")+'</h2><p>Server-validated check-ins</p></div></div></section><section class="section"><div class="grid two"><div class="panel"><p class="eyebrow">FITNESS TRIAL</p><h2>THE TITAN 5</h2><div class="progress">'+sessionCards+'</div></div><div class="panel"><p class="eyebrow">DAILY TRIAL</p><h2>THE 7-DAY STANDARD</h2><div class="daygrid">'+dayCards+'</div></div></div></section><section class="section"><div class="panel center">'+(pass?'<p class="eyebrow">VERIFIED</p><h2>TITAN PASS</h2><h3 style="letter-spacing:.18em">'+esc(pass.titan_id)+'</h3><p>Active Titan identity · '+esc(pass.earned_at||"")+'</p>':outcome?'<p class="eyebrow">FINAL OUTCOME</p><h2>'+esc(outcome.outcome.toUpperCase())+'</h2><p>'+esc(outcome.reviewer_notes||"Your attempt has been finalized.")+'</p>':ap.status==="under_review"?'<p class="eyebrow">ORANOS REVIEW</p><h2>UNDER REVIEW</h2><p>Your evidence is being reviewed by the ORANOS team.</p>':'<p class="eyebrow">NEXT STEP</p><h2>CONTINUE YOUR TRIAL</h2><a class="btn primary" href="#/challenge">Continue Fitness</a><a class="btn" href="#/execution">7-Day Check-in</a>')+'</div></section>');
 document.querySelector("#memberSignOut").onclick=async()=>{const {error}=await db.auth.signOut();if(error)return toast(error.message);location.hash="/"};
}
window.adminTimeline=async(id)=>{
 const box=document.querySelector("#adminTimeline");if(!box)return;
 const a=await db.from("titan_applications").select("id,status,started_at,completed_at,timezone,profiles(full_name)").eq("id",id).single();
 const s=await db.from("titan_submissions").select("status,integrity_status,created_at,titan_challenges(name)").eq("application_id",id).order("created_at");
 const d=await db.from("titan_daily_checkins").select("day_number,pillar_code,completed,checkin_date,reviewer_status").eq("application_id",id).order("day_number");
 const decl=await db.from("titan_declarations").select("status,integrity_status,created_at").eq("application_id",id).order("created_at",{ascending:false}).limit(1).maybeSingle();
 box.innerHTML='<div class="panel"><div class="capturebar"><b>'+esc(a.data?.profiles?.full_name||"Applicant")+'</b><b>'+esc(a.data?.status?.toUpperCase()||"")+'</b></div><p>Timezone: '+esc(a.data?.timezone||"")+'</p><h3>Fitness</h3>'+((s.data||[]).map(x=>'<div class="prog"><span>'+esc(x.titan_challenges?.name||"Trial")+'</span><b>'+esc((x.status||"").toUpperCase())+'</b></div>').join("")||"<p>No submissions.</p>")+'<h3>7-Day Standard</h3>'+[1,2,3,4,5,6,7].map(n=>{const z=(d.data||[]).filter(x=>x.day_number===n);return '<div class="prog"><span>DAY '+n+' · '+esc(z[0]?.checkin_date||"—")+'</span><b>'+esc(z.length?new Set(z.map(x=>x.pillar_code)).size+"/3":"PENDING")+'</b></div>'}).join("")+'<h3>Declaration</h3><div class="prog"><span>'+esc(decl.data?.created_at||"Not submitted")+'</span><b>'+esc(decl.data?.status?.toUpperCase()||"NONE")+'</b></div></div>';
 box.scrollIntoView({behavior:"smooth",block:"start"});
};
async function admin(){
 const {data:{user}}=await db.auth.getUser();if(!user)return location.hash="#/apply";
 const {data:p}=await db.from("profiles").select("role").eq("id",user.id).single();
 if(p?.role!=="admin")return shell('<section class="pagehead center"><h1>ACCESS DENIED</h1></section>');
 const [s,d,a,o]=await Promise.all([
  db.from("titan_submissions").select("*,titan_challenges(name,slug),profiles(full_name),titan_sessions(challenge_code,status)").order("created_at",{ascending:false}),
  db.from("titan_declarations").select("*,profiles(full_name)").order("created_at",{ascending:false}),
  db.from("titan_applications").select("id,user_id,status,created_at,completed_at,timezone,profiles(full_name)").order("created_at",{ascending:false}),
  db.from("titan_outcomes").select("*").order("finalized_at",{ascending:false})
 ]);
 const apps=a.data||[], subs=s.data||[], decls=d.data||[], outs=o.data||[];
 const appCards=apps.map(x=>'<article class="review"><div><b>'+esc(x.profiles?.full_name||"Applicant")+'</b><small>'+esc(x.status)+' · '+esc(x.timezone||"Asia/Kolkata")+'</small><small>'+esc(x.id)+'</small></div><div class="actions"><button class="btn" onclick="adminApplicant(\''+x.id+'\')">View Timeline</button></div></article>').join("");
 shell('<section class="pagehead"><p class="eyebrow">ORANOS ADMIN</p><h1>TITAN COMMAND</h1><p>Review evidence, inspect integrity, and finalize attempts.</p></section><section class="section"><h2>APPLICATIONS</h2><div id="adminApps">'+(appCards||"<p>No applications.</p>")+'</div></section><section class="section"><h2>FITNESS EVIDENCE</h2><div id="reviewerPanel">'+(subs.map(x=>'<article class="review"><div><b>'+esc(x.profiles?.full_name||"Applicant")+'</b><small>'+esc(x.titan_challenges?.name||"Challenge")+' · '+esc(x.titan_sessions?.challenge_code||"")+'</small><small>'+esc(x.status)+' · '+esc(x.integrity_status||"review")+'</small></div><div class="actions">'+(x.video_path?'<button class="btn" onclick="viewVideo(\''+x.id+'\')">Video</button>':"")+'<button class="btn" onclick="viewSignals(\''+x.id+'\')">Signals</button><button class="btn" onclick="review(\''+x.id+'\',\'approved\')">Approve</button><button class="btn" onclick="review(\''+x.id+'\',\'reattempt\')">Reattempt</button><button class="btn" onclick="review(\''+x.id+'\',\'rejected\')">Reject</button></div></article>').join("")||"<p>No submissions.</p>")+'</div></section><section class="section"><h2>DECLARATIONS</h2><div id="declarationReview">'+(decls.map(x=>'<article class="review"><div><b>'+esc(x.profiles?.full_name||"Applicant")+'</b><small>'+esc(x.status)+' · '+esc(x.integrity_status||"review")+'</small></div><div class="actions"><button class="btn" onclick="viewDeclarationVideo(\''+x.id+'\')">Video</button><button class="btn" onclick="reviewDeclaration(\''+x.id+'\',\'approved\')">Approve</button><button class="btn" onclick="reviewDeclaration(\''+x.id+'\',\'reattempt\')">Reattempt</button><button class="btn" onclick="reviewDeclaration(\''+x.id+'\',\'rejected\')">Reject</button><button class="btn primary" onclick="finalizeTitan(\''+x.application_id+'\',\'passed\')">FINALIZE PASS</button><button class="btn" onclick="finalizeTitan(\''+x.application_id+'\',\'failed\')">FINALIZE FAIL</button></div></article>').join("")||"<p>No declarations.</p>")+'</div><div id="videoViewer"></div></section><section class="section"><h2>FINAL OUTCOMES</h2><div>'+(outs.map(x=>'<article class="review"><b>'+esc(x.outcome.toUpperCase())+'</b><small>'+esc(x.titan_id||"No Titan ID")+'</small><small>Evidence purged: '+esc(x.evidence_files_deleted)+'</small></article>').join("")||"<p>No finalized attempts.</p>")+'</div></section>');
 window.adminApplicant=async(id)=>{
  const [app,checks]=await Promise.all([
   db.from("titan_applications").select("*,profiles(full_name)").eq("id",id).single(),
   db.from("titan_daily_checkins").select("*").eq("application_id",id).order("day_number")
  ]);
  const x=app.data, rows=checks.data||[];
  document.querySelector("#videoViewer").innerHTML='<div class="capture"><div class="capturebar"><b>APPLICANT TIMELINE</b><button class="btn" onclick="document.querySelector(\'#videoViewer\').innerHTML=\'\'">Close</button></div><h3>'+esc(x?.profiles?.full_name||"Applicant")+'</h3><p>Status: '+esc(x?.status||"")+' · Timezone: '+esc(x?.timezone||"Asia/Kolkata")+'</p><div class="daygrid">'+[1,2,3,4,5,6,7].map(n=>'<div class="daybox '+(new Set(rows.filter(r=>r.day_number===n&&r.completed).map(r=>r.pillar_code)).size===3?"complete":"")+'"><b>DAY '+n+'</b><span>'+rows.filter(r=>r.day_number===n&&r.completed).map(r=>r.pillar_code.toUpperCase()).join(" · ")+'</span></div>').join("")+'</div></div>';
  document.querySelector("#videoViewer").scrollIntoView({behavior:"smooth",block:"center"});
 };
}window.review=async(id,decision)=>{if(!["approved","reattempt","rejected"].includes(decision))return toast("Invalid review decision.");const {data:{user}}=await db.auth.getUser();if(!user)return location.hash="#/apply";const notes=prompt("Reviewer note (optional)","");if(notes===null)return;const sub=await db.from("titan_submissions").select("id,user_id,application_id,session_id").eq("id",id).single();if(sub.error)return toast(sub.error.message);const u=await db.from("titan_submissions").update({status:decision,reviewer_notes:notes,reviewed_at:new Date().toISOString(),reviewed_by:user.id}).eq("id",id);if(u.error)return toast(u.error.message);if(sub.data.session_id){const ss=await db.from("titan_sessions").update({status:decision==="approved"?"approved":decision}).eq("id",sub.data.session_id);if(ss.error)return toast(ss.error.message)}const rv=await db.from("titan_reviews").insert({submission_id:id,reviewer_id:user.id,decision,notes});if(rv.error)return toast(rv.error.message);toast("Review saved. Final Titan outcome requires separate server-side finalization.");admin()}

