function titanExecution(){shell('<section class="pagehead"><p class="eyebrow">TITAN V2 · EXECUTION</p><h1>SEVEN DAYS.<br>FOUR PILLARS.</h1><p>Consistency is the trial.</p></section><section class="section"><div class="card center"><p class="eyebrow">DAILY ACCOUNTABILITY</p><h2>DAY 1 → DAY 7</h2><p>Complete your commitments honestly and submit your daily check-in.</p><div class="progress"><span style="width:14%"></span></div><button class="btn primary" id="checkin">Complete today’s check-in</button><p id="checkinStatus" class="muted"></p></div></section><section class="section"><div class="grid four">'+TITAN_V2_PILLARS.map((p,i)=>'<article class="card"><p class="eyebrow">'+p[1]+' PILLAR '+(i+1)+'</p><h3>'+p[0]+'</h3><p>'+p[2]+'</p><p class="muted">'+p[4]+'</p></article>').join('')+'</div></section>');document.querySelector('#checkin').onclick=async()=>{const {data:{user}}=await db.auth.getUser();if(!user)return account();const {data:apps}=await db.from('titan_applications').select('id').eq('user_id',user.id).order('created_at',{ascending:false}).limit(1);if(!apps?.[0])return toast('Start your Titan application first.');for(const pillar of ['mindset','lifestyle','discipline'])await db.from('titan_daily_checkins').upsert({user_id:user.id,application_id:apps[0].id,pillar_code:pillar,day_number:1,checkin_date:new Date().toISOString().slice(0,10),completed:true,evidence:{source:'web_checkin'}},{onConflict:'user_id,application_id,pillar_code,day_number'});document.querySelector('#checkinStatus').textContent='Day 1 check-in saved. Continue daily for 7 days.'}}
