async function declarationRecord(){const box=document.querySelector('#declareBox');box.innerHTML='<video id="declareVideo" autoplay muted playsinline></video><div class="actions"><button class="btn primary" id="declareRec">Start recording</button><button class="btn" id="declareStop" disabled>Stop & submit</button></div>';const v=document.querySelector('#declareVideo');let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});v.srcObject=stream}catch(e){return toast('Camera and microphone permission is required.')}let rec,chunks=[];document.querySelector('#declareRec').onclick=()=>{chunks=[];rec=new MediaRecorder(stream);rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);rec.onstop=async()=>{const blob=new Blob(chunks,{type:rec.mimeType||'video/webm'});const {data:{user}}=await db.auth.getUser();const {data:apps}=await db.from('titan_applications').select('id').eq('user_id',user.id).order('created_at',{ascending:false}).limit(1);if(!apps?.[0])return toast('Titan application not found.');const path=user.id+'/declaration-'+Date.now()+'.webm';const up=await db.storage.from('titan-videos').upload(path,blob,{contentType:rec.mimeType||'video/webm'});if(up.error)return toast(up.error.message);const r=await db.from('titan_declarations').insert({user_id:user.id,application_id:apps[0].id,video_path:path,integrity_status:'review',integrity_signals:{continuous_recording:true,chunk_count:chunks.length,blob_bytes:blob.size},status:'under_review'});if(r.error)return toast(r.error.message);stream.getTracks().forEach(t=>t.stop());box.innerHTML='<div class="card center"><h2>DECLARATION SUBMITTED</h2><p>Awaiting human review.</p></div>'};rec.start();document.querySelector('#declareRec').disabled=true;document.querySelector('#declareStop').disabled=false;document.querySelector('#declareStop').onclick=()=>{document.querySelector('#declareStop').disabled=true;rec.stop()}};}

