 if(a.status==="reattempt"){return shell('<section class="pagehead center"><p class="eyebrow">TITAN V2</p><h1>REATTEMPT REQUIRED</h1><p>A calendar day was missed. This attempt is closed and a new attempt is required.</p><button class="btn primary" id="restartTitan">Start New Attempt</button></section>'),document.querySelector("#restartTitan").onclick=async()=>{const r=await db.rpc("titan_restart_attempt");if(r.error)return toast(r.error.message);toast("New Titan attempt started.");location.hash="#/challenge"};}
 const {data:subs}=await db.from("titan_submissions").select("challenge_id,status").eq("application_id",a.id).eq("status","approved");
 if(new Set((subs||[]).map(x=>x.challenge_id)).size<5){toast("Finish Fitness first.");return location.hash="#/challenge";}
