async function issueTitanPassIfReady(userId,applicationId){const {data:s}=await db.from("titan_submissions").select("challenge_id").eq("application_id",applicationId).eq("status","approved");const {data:d}=await db.from("titan_daily_checkins").select("day_number,pillar_code").eq("application_id",applicationId).eq("completed",true);const {data:decl}=await db.from("titan_declarations").select("id").eq("application_id",applicationId).eq("status","approved").limit(1);const fitness=new Set((s||[]).map(x=>x.challenge_id)).size>=5;const seven=[1,2,3,4,5,6,7].every(n=>new Set((d||[]).filter(x=>x.day_number===n).map(x=>x.pillar_code)).size===3);if(!fitness||!seven||!(decl||[]).length)return;const {data:old}=await db.from("titan_passes").select("id,titan_id").eq("application_id",applicationId).maybeSingle();if(old)return;const titanId="TITAN-"+crypto.randomUUID().replaceAll("-","").slice(0,10).toUpperCase();const r=await db.from("titan_passes").insert({user_id:userId,application_id:applicationId,titan_id:titanId}).select().single();if(r.error)return toast(r.error.message);await db.from("titan_applications").update({status:"passed",completed_at:new Date().toISOString()}).eq("id",applicationId);toast("TITAN VERIFIED · "+titanId)}
async function admin(){const {data:{user}}=await db.auth.getUser();if(!user)return location.hash="#/apply";const p=await db.from("profiles").select("role").eq("id",user.id).single();if(p?.role!=="admin")return shell('<section class="pagehead center"><h1>ACCESS DENIED</h1></section>');const s=await db.from("titan_submissions").select("*,titan_challenges(*),profiles(full_name),titan_sessions(challenge_code,status)").order("created_at",{ascending:false});const d=await db.from("titan_declarations").select("*,profiles(full_name)").order("created_at",{ascending:false});shell('<section class="pagehead"><p class="eyebrow">ORANOS ADMIN</p><h1>TITAN REVIEW</h1><p>Review physical evidence and final declarations.</p></section><section class="section"><h2>FITNESS</h2><div id="reviewerPanel">'+((s.data||[]).map(x=>'<article class="review"><div><b>'+esc(x.profiles?.full_name||"Applicant")+'</b><small>'+esc(x.titan_challenges?.name||"Challenge")+' · '+esc(x.titan_sessions?.challenge_code||"")+'</small><small>'+esc(x.status)+' · '+esc(x.integrity_status||"review")+'</small></div><span class="status">'+esc(x.integrity_status||"REVIEW")+'</span><div class="actions">'+(x.video_path?'<button class="btn" onclick="viewVideo(\''+x.id+'\')">Video</button>':"")+'<button class="btn" onclick="viewSignals(\''+x.id+'\')">Signals</button><button class="btn" onclick="review(\''+x.id+'\',\'approved\')">Approve</button><button class="btn" onclick="review(\''+x.id+'\',\'reattempt\')">Reattempt</button><button class="btn" onclick="review(\''+x.id+'\',\'rejected\')">Reject</button></div></article>').join("")||"<p>No submissions.</p>")+'</div></section><section class="section"><h2>FINAL DECLARATIONS</h2><div id="declarationReview">'+((d.data||[]).map(x=>'<article class="review"><div><b>'+esc(x.profiles?.full_name||"Applicant")+'</b><small>'+esc(x.status)+' · '+esc(x.integrity_status||"review")+'</small></div><span class="status">'+esc(x.status)+'</span><div class="actions"><button class="btn" onclick="viewDeclarationVideo(\''+x.id+'\')">Video</button><button class="btn" onclick="reviewDeclaration(\''+x.id+'\',\'approved\')">Approve</button><button class="btn" onclick="reviewDeclaration(\''+x.id+'\',\'reattempt\')">Reattempt</button><button class="btn" onclick="reviewDeclaration(\''+x.id+'\',\'rejected\')">Reject</button></div></article>').join("")||"<p>No declarations.</p>")+'</div><div id="videoViewer"></div></section>')}
window.review=async(id,decision)=>{if(!["approved","reattempt","rejected"].includes(decision))return toast("Invalid review decision.");const {data:{user}}=await db.auth.getUser();if(!user)return location.hash="#/apply";const notes=prompt("Reviewer note (optional)","");if(notes===null)return;const sub=await db.from("titan_submissions").select("id,user_id,application_id,session_id").eq("id",id).single();if(sub.error)return toast(sub.error.message);const u=await db.from("titan_submissions").update({status:decision,reviewer_notes:notes,reviewed_at:new Date().toISOString(),reviewed_by:user.id}).eq("id",id);if(u.error)return toast(u.error.message);if(sub.data.session_id){const ss=await db.from("titan_sessions").update({status:decision==="approved"?"approved":decision}).eq("id",sub.data.session_id);if(ss.error)return toast(ss.error.message)}const rv=await db.from("titan_reviews").insert({submission_id:id,reviewer_id:user.id,decision,notes});if(rv.error)return toast(rv.error.message);toast("Review saved. Final Titan outcome requires separate server-side finalization.");admin()}
